// The S60v2 -> S60v3 import map: for every import ordinal an old game can use, what it was and how
// (or whether) it can be reached in v3.
//
// The DATA lives in importmap_data.cpp, GENERATED by tools/gen_importmap.py from games/*/map*.csv
// (output of v2_to_v3.py, one file per game) plus the hand decisions in tools/importmap_curated.csv.
// Do not edit the data by hand. This header and importmap.cpp (the lookup) are hand-written.
#ifndef IMPORTMAP_H
#define IMPORTMAP_H

#include <e32def.h>
#include <e32std.h>

enum TImportKind
    {
    EDirect = 0,            // same signature in v3: new = v3 ordinal
    EShimNeeded = 1,        // no v3 export (became inline, removed, ...): a host shim is required
    EVirtualSlot = 2,       // virtual function in v3: no export, reached through the vtable (curated only)
    ECompilerHelper = 3,    // __divsi3, __builtin_new ...: runtime helper, rtshim or host shim
    ENoV3Lib = 4,           // the v3 DLL does not exist at all (e.g. plpvariant)
    EAmbiguous = 5,         // ctor/dtor: several v3 variants (C1/C2, D0/D1/D2), new = chosen one, informational only
    ESigChanged = 6,        // same name in v3 but the signature differs: new = 0, never bind blindly
    EOverloaded = 7         // several v3 overloads fit, none chosen: decide by hand
    };

struct TImportMapEntry
    {
    TUint8 iDll;            // index into KImportMapDllNames (names sorted alphabetically)
    TUint16 iOld;           // ordinal in the old (v2) DLL
    TUint16 iNew;           // ordinal in the v3 DLL, 0 = none
    TUint8 iKind;           // TImportKind
    };

// Data from importmap_data.cpp. KImportMap is sorted by (iDll, iOld) and has unique keys.
extern const TInt KImportMapDllCount;
extern const char* const KImportMapDllNames[];
extern const TInt KImportMapCount;
extern const TImportMapEntry KImportMap[];

// Lookup in importmap.cpp.
const TText8* ImportMapDllName(TInt aIndex);                                // "" if aIndex is out of range
const TImportMapEntry* ImportMapFind(const TDesC8& aDll, TInt aOld);       // aDll: lower case, no ".dll"; NULL = not in map

#endif
